begin;
create table public.mpesa_checkouts(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id),checkout_request_id text not null unique,merchant_request_id text,phone text not null,expected_amount numeric(14,2) not null,status text not null default 'PENDING' check(status in('PENDING','COMPLETED','FAILED')),result_code integer,result_description text,receipt_number text unique,actual_amount numeric(14,2),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),completed_at timestamptz,raw_metadata jsonb not null default '{}'::jsonb);
alter table public.mpesa_checkouts enable row level security;
create policy mpesa_checkout_owner_read on public.mpesa_checkouts for select to authenticated using(public.is_admin() or exists(select 1 from public.campaigns c where c.id=campaign_id and public.can_manage_artist(c.artist_account_id)));
grant select on public.mpesa_checkouts to authenticated;

create function public.register_mpesa_checkout(p_campaign_id uuid,p_checkout_id text,p_merchant_id text,p_phone text) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.current_profile_id();c public.campaigns;rid uuid;begin select * into c from public.campaigns where id=p_campaign_id for update;if actor is null or c.id is null or not public.can_manage_artist(c.artist_account_id) then raise exception 'NOT_AUTHORIZED';end if;if c.funding_status='FUNDED' then raise exception 'ALREADY_FUNDED';end if;insert into public.mpesa_checkouts(campaign_id,checkout_request_id,merchant_request_id,phone,expected_amount,created_by)values(c.id,p_checkout_id,p_merchant_id,p_phone,c.total_budget,actor)returning id into rid;update public.campaigns set funding_status='PENDING' where id=c.id;return rid;end$$;
grant execute on function public.register_mpesa_checkout(uuid,text,text,text) to authenticated;

create function public.complete_mpesa_checkout(p_checkout_id text,p_result_code integer,p_result_description text,p_receipt text,p_amount numeric,p_proof text) returns jsonb language plpgsql security definer set search_path='' as $$declare x public.mpesa_checkouts;c public.campaigns;policy jsonb;cw uuid;pw uuid;fee numeric(14,2);transfer uuid:=gen_random_uuid();expected text;begin expected:=encode(hmac(p_checkout_id||':'||p_result_code||':'||coalesce(p_receipt,''),current_setting('app.settings.mpesa_callback_secret',true),'sha256'),'hex');if expected is null or expected='' or expected<>p_proof then raise exception 'INVALID_PROOF';end if;select * into x from public.mpesa_checkouts where checkout_request_id=p_checkout_id for update;if x.id is null then raise exception 'CHECKOUT_NOT_FOUND';end if;if x.status<>'PENDING' then return jsonb_build_object('duplicate',true);end if;select * into c from public.campaigns where id=x.campaign_id for update;if p_result_code<>0 then update public.mpesa_checkouts set status='FAILED',result_code=p_result_code,result_description=left(p_result_description,500),completed_at=now() where id=x.id;update public.campaigns set funding_status='NOT_FUNDED' where id=c.id;return jsonb_build_object('status','FAILED');end if;if p_amount<>x.expected_amount or coalesce(p_receipt,'')='' then raise exception 'PAYMENT_MISMATCH';end if;select value into policy from public.business_settings where key='finance_policy';insert into public.wallets(owner_type,campaign_id,wallet_type,currency)values('CAMPAIGN',c.id,'CAMPAIGN_BUDGET','KES')on conflict do nothing;select id into cw from public.wallets where campaign_id=c.id and wallet_type='CAMPAIGN_BUDGET';insert into public.wallets(owner_type,profile_id,wallet_type,currency)values('PROFILE',x.created_by,'OPERATING','KES')on conflict do nothing;select id into pw from public.wallets where profile_id=x.created_by and wallet_type='OPERATING' and currency='KES';fee=round((p_amount*(policy->>'platform_commission_bps')::integer)/10000,2);insert into public.ledger_transactions(wallet_id,transaction_type,direction,amount,currency,reference_type,reference_id,description,status,idempotency_key,posted_at,transfer_id,created_by,metadata)values(cw,'CAMPAIGN_FUNDING','CREDIT',p_amount,'KES','mpesa_checkout',x.id,'M-Pesa campaign funding','POSTED','mpesa:'||p_checkout_id||':funding',now(),transfer,x.created_by,jsonb_build_object('receipt',p_receipt)),(cw,'PLATFORM_COMMISSION','DEBIT',fee,'KES','mpesa_checkout',x.id,'Sauti platform fee','POSTED','mpesa:'||p_checkout_id||':fee-debit',now(),transfer,x.created_by,'{}'),(pw,'PLATFORM_COMMISSION','CREDIT',fee,'KES','mpesa_checkout',x.id,'Sauti platform fee','POSTED','mpesa:'||p_checkout_id||':fee-credit',now(),transfer,x.created_by,'{}');update public.mpesa_checkouts set status='COMPLETED',result_code=0,result_description=p_result_description,receipt_number=p_receipt,actual_amount=p_amount,completed_at=now() where id=x.id;update public.campaigns set funding_status='FUNDED' where id=c.id;insert into public.financial_events(event_type,entity_type,entity_id,actor_profile_id,idempotency_key,payload)values('campaign.funded','campaign',c.id,x.created_by,'mpesa-funded:'||p_checkout_id,jsonb_build_object('gross',p_amount,'receipt',p_receipt));return jsonb_build_object('status','COMPLETED');end$$;
revoke execute on function public.complete_mpesa_checkout(text,integer,text,text,numeric,text) from public,authenticated;grant execute on function public.complete_mpesa_checkout(text,integer,text,text,numeric,text) to anon;
commit;
